1	"use client";
2	
3	/**
4	 * GameCoverCarousel — the premium hero cover carousel on /game-servers.
5	 *
6	 * A coverflow-style row of portrait "box-art" cover cards. The centered card is
7	 * enlarged with a brand glow ring and shows an interactive player-slot selector;
8	 * side cards recede (scale + dim + lift) so the focus reads instantly. Fully
9	 * hand-driven motion — NO native scroll-snap — so it feels high-end:
10	 *
11	 *   • Momentum drag / swipe: pointer + touch, with velocity-based flick that can
12	 *     skip multiple cards and always settles (snaps) on a card via a spring.
13	 *   • Trackpad / wheel: horizontal intent nudges the carousel (vertical page
14	 *     scroll is never hijacked).
15	 *   • ◀ ▶ arrows, ← → / Home / End keyboard, and clickable dot indicators.
16	 *   • Autoplay that pauses on hover, focus, drag, tab-hidden, or reduced-motion.
17	 *   • Continuous depth: every card's scale/opacity/offset is recomputed each
18	 *     frame from the live fractional position, so scaling tracks the drag fluidly.
19	 *   • prefers-reduced-motion: autoplay off, transitions become instant snaps.
20	 *
21	 * ── Cover art (owner drop-in) ────────────────────────────────────────────────
22	 * Resolution chain, first that loads wins (all plain <img> so onError advances
23	 * client-side):
24	 *   1. /games/art/<artSlug>_poster.jpg   ← real portrait key-art (ships today)
25	 *   2. /logos/games/covers/<family>.{webp,jpg,png}   ← owner cover drop-in
26	 *   3. /logos/games/<family>.png         ← owner wordmark on the brand gradient
27	 *   4. per-game gradient + emoji glyph    ← never blank
28	 *
29	 * Every price / slot / spec is read live from the DB game-plan tiers passed in
30	 * (ShowcaseGame) — no invented player counts or prices.
31	 */
32	
33	import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
34	import Link from "next/link";
35	import { GameLogo, GAME_VISUAL } from "../GameLogo";
36	import { IconArrow, IconUsers, IconBolt } from "../icons";
37	import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";
38	import type { ShowcaseGame } from "./GameShowcaseCarousel";
39	import { GameParticleField } from "./GameParticleField";
40	
41	/* ── formatting helpers (DB figures in, display strings out) ─────────────────── */
42	function money(cents: number) {
43	  const v = cents / 100;
44	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
45	}
46	function gb(mb: number) {
47	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
48	}
49	function per(term: number) {
50	  return term > 1 ? `/ ${term} mo` : "/mo";
51	}
52	
53	const NEUTRAL = { from: "#334155", to: "#64748b" };
54	
55	/** Family id → real key-art slugs (public/games/art/), shared with
56	 *  GameCoverTile + GameHero — see lib/games.ts's GAME_ART_SLUG doc comment. */
57	function artSlugFor(family: string) {
58	  return GAME_ART_SLUG[family as GameFamily];
59	}
60	
61	/**
62	 * Ambient backdrop glow behind the whole carousel, colour-matched to the
63	 * CENTERED game via its own GAME_VISUAL brand colours. Remounts on family
64	 * change (`key`) so each new colour crossfades in over the previous one via a
65	 * plain opacity transition.
66	 *
67	 * This used to be the centered game's blurred hero PHOTO, radial-masked to
68	 * fade out. It never fully worked: a mask fading an image to transparent
69	 * still bottoms out at that image's own rectangular bounds, and depending on
70	 * viewport size the mask's taper could land partly off-screen, leaving a
71	 * visible straight edge behind the card instead of a bleed into the page
72	 * background. A pure `radial-gradient` has no image content and therefore no
73	 * rectangle to reveal — it is transparent by construction well before it
74	 * reaches this div's edges, so the "sharp cutoff" this replaces cannot recur
75	 * here regardless of viewport size. Two soft, offset radial layers rather than
76	 * one so the glow reads as a diffuse field instead of a single centered dot.
77	 */
78	function HeroBackdrop({ family }: { family: string }) {
79	  const visual = GAME_VISUAL[family] ?? { ...NEUTRAL };
80	  const [loaded, setLoaded] = useState(false);
81	  useIsoLayoutEffect(() => {
82	    setLoaded(false);
83	    const id = requestAnimationFrame(() => setLoaded(true));
84	    return () => cancelAnimationFrame(id);
85	  }, [family]);
86	  return (
87	    <div
88	      key={family}
89	      aria-hidden
90	      className={`pointer-events-none absolute -inset-x-16 -inset-y-24 -z-10 sm:-inset-x-24 transition-opacity duration-700 ease-out ${loaded ? "opacity-100" : "opacity-0"}`}
91	      style={{
92	        background: [
93	          `radial-gradient(42% 50% at 50% 42%, ${visual.from}70, transparent 72%)`,
94	          `radial-gradient(34% 42% at 50% 56%, ${visual.to}55, transparent 78%)`,
95	        ].join(", "),
96	      }}
97	    />
98	  );
99	}
100	
101	/* ── responsive geometry (must match the card markup below) ──────────────────── */
102	const MOMENTUM = 0.9; // how far a flick's velocity carries (in card-units)
103	const MAX_FLICK = 3; // cap cards skipped by a single flick
104	
105	/** Portrait cover: real poster art if present, else cover drop-in, else wordmark. */
106	function GamePoster({ family, name }: { family: string; name: string }) {
107	  const visual = GAME_VISUAL[family] ?? { name, glyph: "🎮", ...NEUTRAL };
108	  const slug = artSlugFor(family)?.poster;
109	  const chain = [
110	    slug ? `/games/art/${slug}_poster.jpg` : "",
111	    `/logos/games/covers/${family}.webp`,
112	    `/logos/games/covers/${family}.jpg`,
113	    `/logos/games/covers/${family}.png`,
114	    `/logos/games/${family}.png`, // wordmark fallback
115	  ].filter(Boolean) as string[];
116	
117	  const [idx, setIdx] = useState(0);
118	  const src = chain[idx];
119	  const exhausted = idx >= chain.length;
120	  const isWordmark = !exhausted && idx === chain.length - 1;
121	
122	  return (
123	    <div
124	      className="absolute inset-0"
125	      style={{ background: `radial-gradient(130% 100% at 50% 0%, ${visual.from}, ${visual.to})` }}
126	    >
127	      {(isWordmark || exhausted) && (
128	        <div
129	          aria-hidden
130	          className="absolute inset-0 opacity-70 mix-blend-overlay"
131	          style={{ background: "radial-gradient(75% 55% at 50% 32%, rgba(255,255,255,0.28), transparent 72%)" }}
132	        />
133	      )}
134	      {exhausted ? (
135	        <div className="absolute left-1/2 top-[36%] -translate-x-1/2 -translate-y-1/2">
136	          <GameLogo family={family} size={88} />
137	        </div>
138	      ) : (
139	        // eslint-disable-next-line @next/next/no-img-element -- onError fallback chain needs a plain <img>
140	        <img
141	          key={src}
142	          src={src}
143	          alt={`${name} cover art`}
144	          draggable={false}
145	          onError={() => setIdx((i) => i + 1)}
146	          className={
147	            isWordmark
148	              ? "absolute left-1/2 top-[38%] w-[62%] max-w-[190px] -translate-x-1/2 -translate-y-1/2 select-none object-contain drop-shadow-2xl"
149	              : "absolute inset-0 h-full w-full select-none object-cover"
150	          }
151	        />
152	      )}
153	      {/* Readability scrim so the title/price overlay is always legible. */}
154	      <div
155	        aria-hidden
156	        className="absolute inset-x-0 bottom-0 h-3/4"
157	        style={{ background: "linear-gradient(to top, rgba(4,7,15,0.96), rgba(4,7,15,0.45) 48%, transparent)" }}
158	      />
159	    </div>
160	  );
161	}
162	
163	/** Interactive player-slot selector for the active card (all figures DB-fed). */
164	function SlotSelector({ game }: { game: ShowcaseGame }) {
165	  const slotted = game.tiers.filter((t) => t.slots != null);
166	  const options = slotted.length ? slotted : game.tiers;
167	  const defaultIdx = Math.max(0, options.findIndex((t) => t.featured));
168	  const [sel, setSel] = useState(defaultIdx === -1 ? 0 : defaultIdx);
169	  const tier = options[sel] ?? game.tiers[0];
170	  if (!tier) return null;
171	
172	  return (
173	    <div className="mt-3">
174	      {slotted.length > 0 && (
175	        <>
176	          <p className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-300/80">
177	            <IconUsers size={12} /> Players
178	          </p>
179	          <div className="mt-1.5 flex flex-wrap gap-1.5" role="group" aria-label={`${game.name} player slots`}>
180	            {options.map((t, i) => (
181	              <button
182	                key={`${t.name}-${i}`}
183	                type="button"
184	                aria-pressed={i === sel}
185	                onPointerDown={(e) => e.stopPropagation()}
186	                onClick={(e) => {
187	                  e.stopPropagation();
188	                  setSel(i);
189	                }}
190	                className={`rounded-md border px-2 py-0.5 text-xs font-semibold transition-colors ${
191	                  i === sel
192	                    ? "border-brand-400/70 bg-brand-500/25 text-white"
193	                    : "border-white/15 bg-black/30 text-slate-200 hover:border-white/30"
194	                }`}
195	              >
196	                {t.slots}
197	              </button>
198	            ))}
199	          </div>
200	        </>
201	      )}
202	      <div
203	        key={sel}
204	        className="mt-2.5 flex items-end justify-between gap-2 motion-safe:animate-[var(--animate-price-pop)]"
205	      >
206	        <div>
207	          <p className="text-[10px] uppercase tracking-wide text-slate-400">Starting at</p>
208	          <p className="text-2xl font-extrabold tracking-tight text-white">
209	            {money(tier.priceCents)}
210	            <span className="ml-1 text-xs font-normal text-slate-300">{per(tier.termMonths)}</span>
211	          </p>
212	        </div>
213	        <span className="flex items-center gap-1 pb-1 text-[11px] text-slate-300">
214	          <IconBolt size={12} className="text-brand-300" /> {gb(tier.ramMB)} · {tier.cpuCores} vCPU
215	        </span>
216	      </div>
217	    </div>
218	  );
219	}
220	
221	/** SSR-safe layout effect (avoids the React useLayoutEffect-on-server warning). */
222	const useIsoLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;
223	
224	export function GameCoverCarousel({ games }: { games: ShowcaseGame[] }) {
225	  const n = games.length;
226	  // Start on the first "Popular" title, else the second card for a coverflow feel.
227	  const initial = (() => {
228	    const f = games.findIndex((g) => g.tiers.some((t) => t.featured));
229	    return f >= 0 ? f : Math.min(1, Math.max(0, n - 1));
230	  })();
231	
232	  const [active, setActive] = useState(initial);
233	  const [ready, setReady] = useState(false);
234	  const [paused, setPaused] = useState(false);
235	
236	  const viewportRef = useRef<HTMLDivElement>(null);
237	  const trackRef = useRef<HTMLDivElement>(null);
238	  const cardRefs = useRef<(HTMLDivElement | null)[]>([]);
239	
240	  const offsetRef = useRef(initial); // live fractional position (in card-units)
241	  const targetRef = useRef(initial);
242	  const rafRef = useRef<number | null>(null);
243	  const reducedRef = useRef(false);
244	  const activeRef = useRef(initial); // mirror for handlers without re-subscribing
245	
246	  const clamp = useCallback((i: number) => Math.max(0, Math.min(n - 1, i)), [n]);
247	
248	  /* Paint one frame: track translate + per-card depth, from offsetRef. */
249	  const paint = useCallback(() => {
250	    const vp = viewportRef.current;
251	    const track = trackRef.current;
252	    const first = cardRefs.current[0];
253	    const second = cardRefs.current[1];
254	    if (!vp || !track || !first) return;
255	
256	    const cardW = first.offsetWidth;
257	    const step = second ? second.offsetLeft - first.offsetLeft : cardW;
258	    const base = first.offsetLeft + cardW / 2; // center of card 0 within the track
259	    const vpCenter = vp.clientWidth / 2;
260	    const off = offsetRef.current;
261	
262	    track.style.transform = `translate3d(${vpCenter - base - off * step}px,0,0)`;
263	
264	    const cards = cardRefs.current;
265	    for (let i = 0; i < cards.length; i++) {
266	      const el = cards[i];
267	      if (!el) continue;
268	      const d = i - off; // signed distance from center, in cards
269	      const a = Math.min(Math.abs(d), 1.6);
270	      const scale = 1.08 - a * 0.19; // center pops, neighbours recede
271	      const lift = a * 14; // side cards drop slightly
272	      const rot = Math.max(-1, Math.min(1, d)) * -5; // faint coverflow tilt
273	      const opacity = 1 - Math.min(a, 1) * 0.5;
274	      el.style.transform = `translateY(${lift}px) scale(${scale}) perspective(1000px) rotateY(${rot}deg)`;
275	      el.style.opacity = `${opacity}`;
276	      el.style.zIndex = `${100 - Math.round(a * 10)}`;
277	    }
278	  }, []);
279	
280	  /* Spring toward targetRef; commit `active` when it settles. */
281	  const animate = useCallback(() => {
282	    const diff = targetRef.current - offsetRef.current;
283	    if (Math.abs(diff) < 0.0015) {
284	      offsetRef.current = targetRef.current;
285	      paint();
286	      rafRef.current = null;
287	      const idx = clamp(Math.round(offsetRef.current));
288	      activeRef.current = idx;
289	      setActive(idx);
290	      return;
291	    }
292	    offsetRef.current += diff * 0.185;
293	    paint();
294	    rafRef.current = requestAnimationFrame(animate);
295	  }, [paint, clamp]);
296	
297	  /* Settle onto a target card (instant when reduced-motion). */
298	  const settleTo = useCallback(
299	    (target: number) => {
300	      targetRef.current = clamp(target);
301	      if (reducedRef.current) {
302	        offsetRef.current = targetRef.current;
303	        paint();
304	        const idx = clamp(Math.round(targetRef.current));
305	        activeRef.current = idx;
306	        setActive(idx);
307	        return;
308	      }
309	      if (rafRef.current == null) rafRef.current = requestAnimationFrame(animate);
310	    },
311	    [animate, paint, clamp],
312	  );
313	
314	  const go = useCallback((i: number) => settleTo(i), [settleTo]);
315	
316	  /* ── mount: detect reduced-motion, first layout, resize + fade-in ──────────── */
317	  useIsoLayoutEffect(() => {
318	    reducedRef.current =
319	      typeof window !== "undefined" &&
320	      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
321	    paint();
322	    setReady(true);
323	    const onResize = () => paint();
324	    window.addEventListener("resize", onResize);
325	    return () => {
326	      window.removeEventListener("resize", onResize);
327	      if (rafRef.current != null) cancelAnimationFrame(rafRef.current);
328	    };
329	    // paint is stable; run once on mount.
330	    // eslint-disable-next-line react-hooks/exhaustive-deps
331	  }, []);
332	
333	  /* ── pointer / touch momentum drag ─────────────────────────────────────────── */
334	  useEffect(() => {
335	    const vp = viewportRef.current;
336	    const track = trackRef.current;
337	    const first = cardRefs.current[0];
338	    const second = cardRefs.current[1];
339	    if (!vp || !track) return;
340	
341	    let dragging = false;
342	    let moved = false;
343	    let startX = 0;
344	    let startOffset = 0;
345	    let lastX = 0;
346	    let lastT = 0;
347	    let velocity = 0; // card-units per ms
348	    let step = second && first ? second.offsetLeft - first.offsetLeft : first?.offsetWidth || 1;
349	
350	    const onDown = (e: PointerEvent) => {
351	      if (e.button != null && e.button !== 0) return;
352	      const f = cardRefs.current[0];
353	      const s = cardRefs.current[1];
354	      step = s && f ? s.offsetLeft - f.offsetLeft : f?.offsetWidth || step;
355	      dragging = true;
356	      moved = false;
357	      startX = lastX = e.clientX;
358	      startOffset = offsetRef.current;
359	      lastT = e.timeStamp;
360	      velocity = 0;
361	      if (rafRef.current != null) {
362	        cancelAnimationFrame(rafRef.current);
363	        rafRef.current = null;
364	      }
365	      setPaused(true);
366	      track.style.transition = "none";
367	      vp.setPointerCapture?.(e.pointerId);
368	    };
369	
370	    const onMove = (e: PointerEvent) => {
371	      if (!dragging) return;
372	      const dx = e.clientX - startX;
373	      if (Math.abs(dx) > 4) moved = true;
374	      offsetRef.current = clamp(startOffset - dx / step);
375	      const dt = e.timeStamp - lastT || 16;
376	      velocity = -(e.clientX - lastX) / step / dt;
377	      lastX = e.clientX;
378	      lastT = e.timeStamp;
379	      paint();
380	    };
381	
382	    const onUp = (e: PointerEvent) => {
383	      if (!dragging) return;
384	      dragging = false;
385	      vp.releasePointerCapture?.(e.pointerId);
386	      // Fold flick velocity into how many cards we travel, then snap.
387	      const flick = Math.max(-MAX_FLICK, Math.min(MAX_FLICK, velocity * 1000 * MOMENTUM));
388	      const target = clamp(Math.round(offsetRef.current + flick));
389	      settleTo(target);
390	      // Suppress the click that follows a real drag.
391	      if (moved) {
392	        const stop = (ev: Event) => {
393	          ev.stopPropagation();
394	          ev.preventDefault();
395	        };
396	        vp.addEventListener("click", stop, { capture: true, once: true });
397	      }
398	    };
399	
400	    vp.addEventListener("pointerdown", onDown);
401	    window.addEventListener("pointermove", onMove);
402	    window.addEventListener("pointerup", onUp);
403	    window.addEventListener("pointercancel", onUp);
404	    return () => {
405	      vp.removeEventListener("pointerdown", onDown);
406	      window.removeEventListener("pointermove", onMove);
407	      window.removeEventListener("pointerup", onUp);
408	      window.removeEventListener("pointercancel", onUp);
409	    };
410	  }, [clamp, paint, settleTo]);
411	
412	  /* ── trackpad / wheel (horizontal intent only) ─────────────────────────────── */
413	  useEffect(() => {
414	    const vp = viewportRef.current;
415	    if (!vp) return;
416	    let lock = 0;
417	    const onWheel = (e: WheelEvent) => {
418	      const horizontal = Math.abs(e.deltaX) > Math.abs(e.deltaY);
419	      if (!horizontal) return; // never hijack vertical page scroll
420	      e.preventDefault();
421	      const now = e.timeStamp;
422	      if (now - lock < 260) return;
423	      lock = now;
424	      settleTo(clamp(Math.round(targetRef.current) + (e.deltaX > 0 ? 1 : -1)));
425	    };
426	    vp.addEventListener("wheel", onWheel, { passive: false });
427	    return () => vp.removeEventListener("wheel", onWheel);
428	  }, [clamp, settleTo]);
429	
430	  /* ── autoplay (pauses on hover/focus/drag/hidden/reduced-motion) ───────────── */
431	  useEffect(() => {
432	    if (paused || reducedRef.current || n <= 1) return;
433	    const id = window.setInterval(() => {
434	      if (document.hidden) return;
435	      const next = activeRef.current + 1 >= n ? 0 : activeRef.current + 1;
436	      settleTo(next);
437	    }, 4200);
438	    return () => window.clearInterval(id);
439	  }, [paused, n, settleTo]);
440	
441	  if (n === 0) return null;
442	
443	  const onKeyDown = (e: React.KeyboardEvent) => {
444	    if (e.key === "ArrowLeft") {
445	      e.preventDefault();
446	      go(activeRef.current - 1);
447	    } else if (e.key === "ArrowRight") {
448	      e.preventDefault();
449	      go(activeRef.current + 1);
450	    } else if (e.key === "Home") {
451	      e.preventDefault();
452	      go(0);
453	    } else if (e.key === "End") {
454	      e.preventDefault();
455	      go(n - 1);
456	    }
457	  };
458	
459	  return (
460	    <div
461	      className="relative min-w-0"
462	      onMouseEnter={() => setPaused(true)}
463	      onMouseLeave={() => setPaused(false)}
464	      onFocusCapture={() => setPaused(true)}
465	      onBlurCapture={() => setPaused(false)}
466	    >
467	      <HeroBackdrop family={games[active]?.family ?? ""} />
468	      <div className="pointer-events-none absolute -inset-x-16 -inset-y-24 -z-10 overflow-hidden sm:-inset-x-24">
469	        <GameParticleField
